from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import permissions, status
from webpush.models import PushInformation

class WebPushUnsubscribeView(APIView):
    permission_classes = [permissions.IsAuthenticated]

    def delete(self, request, subscription_id):
        # Ensure only the subscription owner can delete it
        push_info = PushInformation.objects.filter(id=subscription_id, user=request.user).first()
        if not push_info:
            return Response({"error": "Subscription not found"}, status=status.HTTP_404_NOT_FOUND)

        push_info.delete()
        return Response({"status": "Unsubscribed successfully"}, status=status.HTTP_200_OK)
